"""ACCESS1 analysis: evaluate P1-P8 from out/access1.json and write the results table. Usage: python3 -I planned/access1_analyze.py"""
import json
D = json.load(open('out/access1.json')); M = D['metros']
res = []
def both(f): return all(f(M[m], m) for m in ('DFW', 'HOU'))
def sc(m, k): return M[m]['scen'][k]
def add(name, ok, detail): res.append((name, ok, detail)); print(('PASS ' if ok else 'FAIL ') + name, detail)
sh = lambda m, k='peak_P20_T10': sc(m, k)['share']
add('P1 share 0.1-3% (peak, P20, T10)', both(lambda r, m: 0.001 <= sh(m) <= 0.03), {m: round(100 * sh(m), 3) for m in M})
add('P2 off-peak share < half of peak', both(lambda r, m: sh(m, 'off_P20_T10') < 0.5 * sh(m)), {m: (round(100 * sh(m, 'off_P20_T10'), 3), round(100 * sh(m), 3)) for m in M})
add('P3 P=10 share > 2x P=20', both(lambda r, m: sh(m, 'peak_P10_T10') > 2 * sh(m)), {m: (round(100 * sh(m, 'peak_P10_T10'), 3), round(100 * sh(m), 3)) for m in M})
add('P4 DFW share > Houston share', sh('DFW') > sh('HOU'), {m: round(100 * sh(m), 3) for m in M})
add('P5 median commute of beneficiaries >= 2x all', both(lambda r, m: sc(m, 'peak_P20_T10')['median_km'] is not None and sc(m, 'peak_P20_T10')['median_km'] >= 2 * r['median_km_all']), {m: (sc(m, 'peak_P20_T10')['median_km'], round(M[m]['median_km_all'], 2)) for m in M})
add('P6 SE03 share of beneficiaries >= all + 10 points', both(lambda r, m: sc(m, 'peak_P20_T10')['se03'] is not None and sc(m, 'peak_P20_T10')['se03'] >= r['se03_all'] + 0.10), {m: (round(sc(m, 'peak_P20_T10')['se03'], 3) if sc(m, 'peak_P20_T10')['se03'] is not None else None, round(M[m]['se03_all'], 3)) for m in M})
cp = lambda m: M[m]['catch']['30']['pop_any'] / M[m]['pop_total']
add('P7 residents within 30 min: DFW 35-75%, HOU 25-65%', 0.35 <= cp('DFW') <= 0.75 and 0.25 <= cp('HOU') <= 0.65, {m: round(100 * cp(m), 1) for m in M})
def top3(m):
    s = sc(m, 'peak_P20_T10'); tot = s['jobs_benefit']; return sum(list(s['pairs'].values())[:3]) / tot if tot else 0
add('P8 top three pairs hold >= half of beneficiaries', both(lambda r, m: top3(m) >= 0.5), {m: round(top3(m), 3) for m in M})
add('K checks failed in run', D['checks_failed'] == 0, D['checks_failed'])
n = sum(1 for r in res[:8] if r[1]); print(f'\n{n} of 8 predictions passed')
# table
L = ['# ACCESS1 results table (generated by planned/access1_analyze.py)\n', f"Calibration: c={D['calibration']['c']:.3f}, v_peak={D['calibration']['v_peak']:.1f} km/h, v_off={D['calibration']['v_off']:.1f} km/h\n"]
for m in M:
    r = M[m]; L += [f"\n## {m}: {r['jobs_all']:.0f} jobs with both ends in the metro; residents {r['pop_total']:.0f}; sites {', '.join(r['sites'])}\n", '| scenario | P | T | beneficiary jobs | share | median commute km | SE03 share |', '|---|---|---|---|---|---|---|']
    for sname in ('peak', 'off'):
        for P in (10, 20, 30):
            for T in (0, 10, 20):
                s = r['scen'][f'{sname}_P{P}_T{T}']; L.append(f"| {sname} | {P} | {T} | {s['jobs_benefit']:.0f} | {100*s['share']:.3f}% | {s['median_km'] if s['median_km'] is None else round(s['median_km'],1)} | {s['se03'] if s['se03'] is None else round(s['se03'],3)} |")
    L.append(f"\nAll jobs: median straight-line commute {r['median_km_all']:.1f} km, SE03 share {r['se03_all']:.3f}.")
    L.append(f"\nTop site pairs (peak, P20, T10): {r['scen']['peak_P20_T10']['pairs']}")
    for lim in ('15', '30'):
        c_ = r['catch'][lim]; L.append(f"\nWithin {lim} min of any site (peak speed): {c_['pop_any']:.0f} residents ({100*c_['pop_any']/r['pop_total']:.1f}%), {c_['jobs_any']:.0f} jobs ({100*c_['jobs_any']/r['jobs_total_wac']:.1f}%). Per site (residents): " + ', '.join(f"{k} {v['pop']:.0f}" for k, v in c_['per_site'].items()))
L.append('\n## Predictions\n'); L += [f"- {'PASS' if ok else 'FAIL'} {n_}: {d}" for n_, ok, d in res]
open('planned/access1_results_table.md', 'w').write('\n'.join(L) + '\n')
